-- =====================================================================
-- Website installed into schema "site04" (generated by scripts/build-schema-sql.mjs).
-- Storage bucket: "site04-media".
-- WARNING: run this file ONCE. Running it again replaces all website content with the demo content
-- (messages and admins are kept).
--
-- AFTER running this file:
--   1. Project Settings → Data API → "Exposed schemas": add site04  (then Save)
--   2. Website .env: NEXT_PUBLIC_SUPABASE_SCHEMA=site04
--   3. Make your owner an admin of this website (bottom of this file).
-- =====================================================================

create schema if not exists site04;
grant usage on schema site04 to anon, authenticated, service_role;
alter default privileges in schema site04 grant all on tables to anon, authenticated, service_role;
alter default privileges in schema site04 grant all on sequences to anon, authenticated, service_role;
alter default privileges in schema site04 grant execute on functions to anon, authenticated, service_role;
-- Row Level Security (enabled on every table below) still decides who can read or write.

-- >>> 0001_init.sql
-- =====================================================================
-- Business Portfolio — initial schema
-- Single-owner portfolio. Public can read published/active content;
-- only users listed in site04.admins (and active) can write.
-- =====================================================================


-- ---------- helpers ----------
create or replace function site04.set_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end $$;

-- ---------- admins (dashboard users) ----------
create table if not exists site04.admins (
  user_id uuid primary key references auth.users (id) on delete cascade,
  display_name text not null default 'Owner',
  avatar_url text,
  role text not null default 'owner' check (role in ('owner')),
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create or replace function site04.is_admin()
returns boolean
language sql stable security definer set search_path = site04
as $$
  select exists (
    select 1 from site04.admins a where a.user_id = auth.uid() and a.active
  );
$$;
revoke all on function site04.is_admin() from public;
grant execute on function site04.is_admin() to anon, authenticated;

-- ---------- site settings (single row) ----------
create table if not exists site04.site_settings (
  id uuid primary key default gen_random_uuid(),
  website_name text not null,
  logo_url text,
  accent_color text not null default '#ff014f' check (accent_color ~* '^#([0-9a-f]{3}|[0-9a-f]{6})$'),
  default_theme text not null default 'dark' check (default_theme in ('dark', 'light', 'system')),
  contact_email text not null,
  public_phone text,
  seo_title text not null,
  seo_description text not null,
  footer_text text not null default '',
  hire_label text not null default 'Hire Me',
  updated_at timestamptz not null default now()
);

-- ---------- profile (single row) ----------
create table if not exists site04.profile (
  id uuid primary key default gen_random_uuid(),
  full_name text not null,
  professional_title text not null,
  typed_roles text[] not null default '{}',
  short_intro text not null default '',
  bio text not null default '',
  email text not null,
  phone text,
  location text not null default '',
  profile_image_url text not null,
  hero_image_url text,
  resume_url text,
  availability_status text not null default '',
  social_links jsonb not null default '[]'::jsonb,
  skill_tools jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ---------- content tables ----------
create table if not exists site04.services (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  short_description text not null,
  icon_key text,
  active boolean not null default true,
  sort_order int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists site04.projects (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  category text not null,
  year int not null,
  client text,
  role text,
  intro text not null,
  challenge text,
  solution text,
  result text,
  cover_image_url text not null,
  gallery jsonb not null default '[]'::jsonb,
  live_url text,
  likes int not null default 0,
  featured boolean not null default false,
  status text not null default 'published' check (status in ('published', 'draft')),
  sort_order int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists site04.resume_items (
  id uuid primary key default gen_random_uuid(),
  type text not null check (type in ('education', 'experience')),
  title text not null,
  subtitle text not null,
  period text not null,
  badge text,
  description text not null default '',
  active boolean not null default true,
  sort_order int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists site04.skills (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  category text not null,
  level int not null default 80 check (level between 0 and 100),
  active boolean not null default true,
  sort_order int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists site04.testimonials (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  role text,
  company text,
  project_title text,
  quote text not null,
  avatar_url text,
  rating int not null default 5 check (rating between 1 and 5),
  active boolean not null default true,
  sort_order int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists site04.clients (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  category text not null default 'Brand',
  logo_url text,
  website_url text,
  active boolean not null default true,
  sort_order int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists site04.pricing_plans (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  tagline text not null default '',
  price text not null,
  period text not null default '',
  description text not null default '',
  features text[] not null default '{}',
  cta_label text not null default 'Order Now',
  highlighted boolean not null default false,
  active boolean not null default true,
  sort_order int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists site04.blog_posts (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  excerpt text not null,
  content text not null,
  cover_image_url text not null,
  category text not null,
  read_time text not null default '3 min read',
  published_at date not null default current_date,
  status text not null default 'published' check (status in ('published', 'draft')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists site04.messages (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 2 and 80),
  email text not null check (char_length(email) between 5 and 120),
  phone text check (phone is null or char_length(phone) <= 30),
  service text check (service is null or char_length(service) <= 80),
  budget text check (budget is null or char_length(budget) <= 40),
  message text not null check (char_length(message) between 10 and 4000),
  is_read boolean not null default false,
  created_at timestamptz not null default now()
);

-- ---------- updated_at triggers ----------
do $$
declare t text;
begin
  foreach t in array array['admins','site_settings','profile','services','projects','resume_items','skills','testimonials','clients','pricing_plans','blog_posts']
  loop
    execute format('drop trigger if exists trg_%1$s_updated on site04.%1$s', t);
    execute format('create trigger trg_%1$s_updated before update on site04.%1$s for each row execute function site04.set_updated_at()', t);
  end loop;
end $$;

-- ---------- Row Level Security ----------
alter table site04.admins enable row level security;
alter table site04.site_settings enable row level security;
alter table site04.profile enable row level security;
alter table site04.services enable row level security;
alter table site04.projects enable row level security;
alter table site04.resume_items enable row level security;
alter table site04.skills enable row level security;
alter table site04.testimonials enable row level security;
alter table site04.clients enable row level security;
alter table site04.pricing_plans enable row level security;
alter table site04.blog_posts enable row level security;
alter table site04.messages enable row level security;

-- admins: a user can read and update only their own row (never role/active via app)
drop policy if exists "admins read self" on site04.admins;
create policy "admins read self" on site04.admins for select to authenticated using (user_id = auth.uid());
drop policy if exists "admins update self" on site04.admins;
create policy "admins update self" on site04.admins for update to authenticated
  using (user_id = auth.uid() and site04.is_admin())
  with check (user_id = auth.uid() and role = 'owner' and active = true);

-- public read policies
drop policy if exists "public read settings" on site04.site_settings;
create policy "public read settings" on site04.site_settings for select using (true);
drop policy if exists "public read profile" on site04.profile;
create policy "public read profile" on site04.profile for select using (true);
drop policy if exists "public read services" on site04.services;
create policy "public read services" on site04.services for select using (active or site04.is_admin());
drop policy if exists "public read projects" on site04.projects;
create policy "public read projects" on site04.projects for select using (status = 'published' or site04.is_admin());
drop policy if exists "public read resume" on site04.resume_items;
create policy "public read resume" on site04.resume_items for select using (active or site04.is_admin());
drop policy if exists "public read skills" on site04.skills;
create policy "public read skills" on site04.skills for select using (active or site04.is_admin());
drop policy if exists "public read testimonials" on site04.testimonials;
create policy "public read testimonials" on site04.testimonials for select using (active or site04.is_admin());
drop policy if exists "public read clients" on site04.clients;
create policy "public read clients" on site04.clients for select using (active or site04.is_admin());
drop policy if exists "public read pricing" on site04.pricing_plans;
create policy "public read pricing" on site04.pricing_plans for select using (active or site04.is_admin());
drop policy if exists "public read posts" on site04.blog_posts;
create policy "public read posts" on site04.blog_posts for select using (status = 'published' or site04.is_admin());

-- admin write policies
do $$
declare t text;
begin
  foreach t in array array['site_settings','profile','services','projects','resume_items','skills','testimonials','clients','pricing_plans','blog_posts']
  loop
    execute format('drop policy if exists "admin insert %1$s" on site04.%1$s', t);
    execute format('create policy "admin insert %1$s" on site04.%1$s for insert to authenticated with check (site04.is_admin())', t);
    execute format('drop policy if exists "admin update %1$s" on site04.%1$s', t);
    execute format('create policy "admin update %1$s" on site04.%1$s for update to authenticated using (site04.is_admin()) with check (site04.is_admin())', t);
    execute format('drop policy if exists "admin delete %1$s" on site04.%1$s', t);
    execute format('create policy "admin delete %1$s" on site04.%1$s for delete to authenticated using (site04.is_admin())', t);
  end loop;
end $$;

-- messages: anyone may submit (validated by CHECK constraints); only admins can read/manage
drop policy if exists "anyone can send message" on site04.messages;
create policy "anyone can send message" on site04.messages for insert to anon, authenticated with check (is_read = false);
drop policy if exists "admin read messages" on site04.messages;
create policy "admin read messages" on site04.messages for select to authenticated using (site04.is_admin());
drop policy if exists "admin update messages" on site04.messages;
create policy "admin update messages" on site04.messages for update to authenticated using (site04.is_admin()) with check (site04.is_admin());
drop policy if exists "admin delete messages" on site04.messages;
create policy "admin delete messages" on site04.messages for delete to authenticated using (site04.is_admin());

-- ---------- Storage ----------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'site04-media',
  'site04-media',
  true,
  5242880, -- 5 MB
  array['image/jpeg', 'image/png', 'image/webp', 'image/avif', 'application/pdf']
)
on conflict (id) do update set
  public = excluded.public,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "public read media [site04]" on storage.objects;
create policy "public read media [site04]" on storage.objects for select using (bucket_id = 'site04-media');
drop policy if exists "admin upload media [site04]" on storage.objects;
create policy "admin upload media [site04]" on storage.objects for insert to authenticated
  with check (bucket_id = 'site04-media' and site04.is_admin()
    and (storage.foldername(name))[1] in ('profile', 'projects', 'services', 'testimonials', 'clients', 'blog', 'documents', 'settings'));
drop policy if exists "admin update media [site04]" on storage.objects;
create policy "admin update media [site04]" on storage.objects for update to authenticated
  using (bucket_id = 'site04-media' and site04.is_admin());
drop policy if exists "admin delete media [site04]" on storage.objects;
create policy "admin delete media [site04]" on storage.objects for delete to authenticated
  using (bucket_id = 'site04-media' and site04.is_admin());


-- >>> 0002_hardening.sql
-- =====================================================================
-- Security hardening (run after 0001_init.sql). Safe to re-run.
-- =====================================================================

-- ---------- Contact form: database-level anti-spam ----------
-- The anon key is public, so someone could call the REST API directly and
-- skip the website's rate limit. This trigger caps volume in the database.
create or replace function site04.messages_guard()
returns trigger
language plpgsql security definer set search_path = site04
as $$
begin
  -- Clients can never set these themselves.
  new.is_read := false;
  new.created_at := now();

  if (select count(*) from site04.messages where created_at > now() - interval '10 minutes') >= 30 then
    raise exception 'Too many messages right now. Please try again later.' using errcode = 'P0001';
  end if;

  if (select count(*) from site04.messages
      where lower(email) = lower(new.email) and created_at > now() - interval '1 hour') >= 3 then
    raise exception 'Too many messages from this email. Please try again later.' using errcode = 'P0001';
  end if;

  if new.email !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'Invalid email.' using errcode = 'P0001';
  end if;

  return new;
end $$;

drop trigger if exists trg_messages_guard on site04.messages;
create trigger trg_messages_guard before insert on site04.messages
for each row execute function site04.messages_guard();

create index if not exists messages_created_at_idx on site04.messages (created_at desc);
create index if not exists messages_email_idx on site04.messages (lower(email));

-- ---------- Storage: stop public listing of files ----------
-- Public buckets serve files by URL without any SELECT policy, so only
-- admins need to list objects (the dashboard uses it to delete old files).
drop policy if exists "public read media [site04]" on storage.objects;
drop policy if exists "admin read media [site04]" on storage.objects;
drop policy if exists "admin read media [site04]" on storage.objects;
create policy "admin read media [site04]" on storage.objects for select to authenticated
  using (bucket_id = 'site04-media' and site04.is_admin());

-- ---------- Admins: users may only edit their name / avatar ----------
revoke update on site04.admins from anon, authenticated;
grant update (display_name, avatar_url) on site04.admins to authenticated;


