do $$
declare t text;
begin
  foreach t in array array['stats', 'process_steps'] loop
    execute format('drop trigger if exists trg_%1$s_updated on site04.%1$s', t);
    execute format('create trigger trg_%1$s_updated before update on site04.%1$s for each row execute function site04.set_updated_at()', t);
    execute format('alter table site04.%1$s enable row level security', t);
    execute format('drop policy if exists "public read %1$s" on site04.%1$s', t);
    execute format('drop policy if exists "admin insert %1$s" on site04.%1$s', t);
    execute format('drop policy if exists "admin update %1$s" on site04.%1$s', t);
    execute format('drop policy if exists "admin delete %1$s" on site04.%1$s', t);
    execute format('drop policy if exists "public read %1$s" on site04.%1$s', t);
    execute format('create policy "public read %1$s" on site04.%1$s for select using (active or site04.is_admin())', t);
    execute format('drop policy if exists "admin insert %1$s" on site04.%1$s', t);
    execute format('create policy "admin insert %1$s" on site04.%1$s for insert to authenticated with check (site04.is_admin())', t);
    execute format('drop policy if exists "admin update %1$s" on site04.%1$s', t);
    execute format('create policy "admin update %1$s" on site04.%1$s for update to authenticated using (site04.is_admin()) with check (site04.is_admin())', t);
    execute format('drop policy if exists "admin delete %1$s" on site04.%1$s', t);
    execute format('create policy "admin delete %1$s" on site04.%1$s for delete to authenticated using (site04.is_admin())', t);
  end loop;
end $$;


