I love taking an idea from a rough sketch to a polished product. Clean code, clear design and fast pages are what I care about most — so my clients can focus on their business while their website quietly does its job.', 'hello@julianhart.demo', '+49 30 1234 5678', 'Berlin, Germany', '/demo/avatar-owner.svg', '/demo/portrait.svg', '', null, '/demo/julian-hart-cv.pdf', 'Available for freelance work', '', '', '/demo/about-wide.svg', array[]::text[], 8, '[]'::jsonb, '[{"label":"Birthday","value":"14.03.1994"},{"label":"Age","value":"32"},{"label":"Address","value":"Torstraße 18, Berlin"},{"label":"Email","value":"hello@julianhart.demo"},{"label":"Phone","value":"+49 30 1234 5678"},{"label":"Nationality","value":"German"},{"label":"Study","value":"TU Berlin"},{"label":"Degree","value":"Master"},{"label":"Interest","value":"Photography, Cycling"},{"label":"Freelance","value":"Available"}]'::jsonb, '[{"platform":"facebook","url":"https://facebook.com/"},{"platform":"x","url":"https://x.com/"},{"platform":"instagram","url":"https://instagram.com/"},{"platform":"dribbble","url":"https://dribbble.com/"},{"platform":"github","url":"https://github.com/"}]'::jsonb, '[]'::jsonb);

